// AWI SEO: perkaya schema AutoDealer (area layanan seluruh Sulsel, bengkel, SPKLU, kontak) – Claude 30 Okt 2026
add_action( 'template_redirect', function () {
	if ( is_admin() || wp_doing_ajax() || is_feed() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return;
	}
	ob_start( 'awi_schema_dealer' );
}, 100 );

function awi_schema_dealer( $html ) {
	if ( ! is_string( $html ) || false === strpos( $html, '"AutoDealer"' ) ) {
		return $html;
	}
	$u     = 'https://byd-makassar.id/';
	$addr  = array( '@type' => 'PostalAddress', 'streetAddress' => 'Jl. Jenderal Ahmad Yani No. 15', 'addressLocality' => 'Makassar', 'addressRegion' => 'Sulawesi Selatan', 'postalCode' => '90174', 'addressCountry' => 'ID' );
	$geo   = array( '@type' => 'GeoCoordinates', 'latitude' => -5.1327178, 'longitude' => 119.4091866 );
	$hours = array(
		array( '@type' => 'OpeningHoursSpecification', 'dayOfWeek' => array( 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday' ), 'opens' => '08:00', 'closes' => '17:00' ),
		array( '@type' => 'OpeningHoursSpecification', 'dayOfWeek' => 'Sunday', 'opens' => '09:00', 'closes' => '17:00' ),
	);
	$kota = array( 'Makassar', 'Parepare', 'Palopo' );
	$kab  = array( 'Gowa', 'Maros', 'Takalar', 'Jeneponto', 'Bantaeng', 'Bulukumba', 'Kepulauan Selayar', 'Sinjai', 'Bone', 'Soppeng', 'Wajo', 'Barru', 'Pangkajene dan Kepulauan', 'Sidenreng Rappang', 'Pinrang', 'Enrekang', 'Tana Toraja', 'Toraja Utara', 'Luwu', 'Luwu Utara', 'Luwu Timur' );
	$area = array( array( '@type' => 'State', 'name' => 'Sulawesi Selatan' ) );
	foreach ( $kota as $k ) {
		$area[] = array( '@type' => 'City', 'name' => 'Kota ' . $k );
	}
	foreach ( $kab as $k ) {
		$area[] = array( '@type' => 'AdministrativeArea', 'name' => 'Kabupaten ' . $k );
	}
	$img = array( $u . 'wp-content/uploads/2026/10/byd-haka-karebosi-gedung.webp', $u . 'wp-content/uploads/2026/10/byd-haka-karebosi-showroom.webp', $u . 'wp-content/uploads/2026/10/byd-haka-karebosi-workshop.webp' );
	$d = array(
		'@context'                  => 'https://schema.org',
		'@type'                     => 'AutoDealer',
		'@id'                       => $u . '#dealer',
		'name'                      => 'BYD Haka Karebosi Makassar',
		'alternateName'             => array( 'BYD Makassar', 'Dealer BYD Makassar', 'Dealer Denza Makassar' ),
		'description'               => 'Dealer resmi mobil listrik BYD dan Denza di Makassar, Sulawesi Selatan. Penjualan, test drive, simulasi kredit, bengkel resmi, suku cadang, garansi, dan SPKLU DC 60 kW untuk pelanggan Makassar dan seluruh Sulsel.',
		'url'                       => $u,
		'logo'                      => $u . 'wp-content/uploads/2026/05/logo-byd-haka-karebosi.png',
		'image'                     => $img,
		'telephone'                 => '+62-822-5945-2349',
		'address'                   => $addr,
		'geo'                       => $geo,
		'hasMap'                    => 'https://maps.app.goo.gl/UnBCgN8yNyF5MNrZ8',
		'openingHoursSpecification' => $hours,
		'priceRange'                => 'Rp213 juta – Rp2,29 miliar',
		'currenciesAccepted'        => 'IDR',
		'paymentAccepted'           => 'Tunai, Kredit, Leasing',
		'brand'                     => array( array( '@type' => 'Brand', 'name' => 'BYD' ), array( '@type' => 'Brand', 'name' => 'Denza' ) ),
		'parentOrganization'        => array( '@type' => 'Organization', 'name' => 'Haka Auto (PT Bumi Hijau Motor)', 'url' => 'https://hakaauto.co.id/' ),
		'areaServed'                => $area,
		'contactPoint'              => array(
			array( '@type' => 'ContactPoint', 'contactType' => 'sales', 'name' => 'AWI, Sales Consultant', 'telephone' => '+62-822-5945-2349', 'areaServed' => 'ID-SN', 'availableLanguage' => array( 'id' ) ),
			array( '@type' => 'ContactPoint', 'contactType' => 'customer service', 'name' => 'Service counter BYD Haka Karebosi', 'telephone' => '+62-811-8884-4234', 'areaServed' => 'ID-SN', 'availableLanguage' => array( 'id' ) ),
		),
		'department'                => array(
			array( '@type' => 'AutoRepair', 'name' => 'Bengkel Resmi BYD Haka Karebosi Makassar', 'url' => $u . 'layanan-sales-service-spare-part-byd-makassar/#service', 'telephone' => '+62-811-8884-4234', 'address' => $addr, 'geo' => $geo, 'image' => $u . 'wp-content/uploads/2026/10/byd-haka-karebosi-workshop.webp', 'openingHoursSpecification' => $hours ),
			array( '@type' => 'AutoPartsStore', 'name' => 'Spare Part Resmi BYD Haka Karebosi Makassar', 'url' => $u . 'layanan-sales-service-spare-part-byd-makassar/#spare-part', 'telephone' => '+62-811-8884-4234', 'address' => $addr, 'image' => $u . 'wp-content/uploads/2026/10/byd-haka-karebosi-service-counter.webp' ),
		),
		'amenityFeature'            => array(
			array( '@type' => 'LocationFeatureSpecification', 'name' => 'SPKLU DC fast charging 60 kW', 'value' => true ),
			array( '@type' => 'LocationFeatureSpecification', 'name' => 'Kids corner', 'value' => true ),
			array( '@type' => 'LocationFeatureSpecification', 'name' => 'Test drive', 'value' => true ),
		),
		'sameAs'                    => array( 'https://maps.app.goo.gl/UnBCgN8yNyF5MNrZ8', 'https://hakaauto.co.id/office?branch=BYD%20Haka%20Karebosi', 'https://www.instagram.com/bydmakassar_/', 'https://www.facebook.com/awixdby' ),
		'potentialAction'           => array( '@type' => 'ReserveAction', 'name' => 'Jadwalkan Test Drive', 'target' => array( '@type' => 'EntryPoint', 'urlTemplate' => $u . 'test-drive/', 'inLanguage' => 'id-ID' ) ),
	);
	$new = '<script type="application/ld+json">' . wp_json_encode( $d, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ) . '</script>';
	return preg_replace( '#<script[^>]*application/ld\+json[^>]*>(?:(?!</script>).)*"AutoDealer"(?:(?!</script>).)*</script>#s', str_replace( '$', '\$', $new ), $html, 1 );
}
